          "index": 4,
          "question": "What would each of the last six complete months look like without its single largest order?",
          "intent": "CHECK",
          "tool": "SQL",
          "why": "Removes the biggest order from every month alike, so June is compared on the same terms as the rest.",
          "status": "DONE",
          "note": "",
          "row_count": 6,
          "truncated": false,
          "sql": "WITH ranked AS (SELECT CAST(DATE_TRUNC('MONTH', o.order_date) AS DATE) AS month, o.total_amount, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('MONTH', o.order_date) ORDER BY o.total_amount DESC) AS rank_in_month FROM public.orders AS o WHERE o.status IN ('completed', 'shipped') AND o.order_date >= DATE_TRUNC('MONTH', CURRENT_DATE) - INTERVAL '6 MONTHS' AND o.order_date < DATE_TRUNC('MONTH', CURRENT_DATE)) SELECT TO_CHAR(month, 'YYYY-MM') AS month, SUM(total_amount) AS revenue, SUM(total_amount) FILTER(WHERE rank_in_month > 1) AS revenue_without_largest_order, MAX(total_amount) AS largest_order FROM ranked GROUP BY month ORDER BY month LIMIT 1000",
